export interface ConnectorConfig {
  /** Stripe secret key (sk_live_... or sk_test_...). */
  stripeSecretKey: string
  /** Injected fetch for testing; defaults to global fetch. */
  fetch?: typeof fetch
}

export interface HubSpotContactWebhookPayload {
  objectId: number
  propertyName: string
  propertyValue: string
  changeSource: string
  eventId: string
  subscriptionId: string
  portalId: string
  appId: string
  occurredAt: number
  subscriptionType: string
  attemptNumber: number
  email: string
  firstname: string
  lastname: string
}

export interface StripeCustomerResponse {
  id: string
  object: string
  email: string
  name: string
  created: number
  livemode: boolean
}

export interface HandleResult {
  stripeCustomerId: string
  stripeCustomer: StripeCustomerResponse
}

function validatePayload(payload: unknown): HubSpotContactWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>

  const requiredFields: Array<keyof HubSpotContactWebhookPayload> = [
    'objectId',
    'propertyName',
    'propertyValue',
    'email',
    'firstname',
  ]
  for (const field of requiredFields) {
    if (p[field] === undefined || p[field] === null || p[field] === '') {
      throw new Error(`Missing required field: ${field}`)
    }
  }

  if (p.propertyName !== 'lifecyclestage') {
    throw new Error(`Expected propertyName 'lifecyclestage', got '${p.propertyName}'`)
  }
  if (p.propertyValue !== 'customer') {
    throw new Error(`Expected propertyValue 'customer', got '${p.propertyValue}'`)
  }

  return payload as HubSpotContactWebhookPayload
}

function buildFullName(firstname: string, lastname: string): string {
  const first = firstname.trim()
  const last = lastname.trim()
  return last ? `${first} ${last}` : first
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const validated = validatePayload(payload)

  const fullName = buildFullName(validated.firstname, validated.lastname)

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://api.stripe.com/v1/customers'
  const body = new URLSearchParams({
    email: validated.email,
    name: fullName,
  }).toString()

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.stripeSecretKey}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Stripe API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const customer = (await response.json()) as StripeCustomerResponse

  return {
    stripeCustomerId: customer.id,
    stripeCustomer: customer,
  }
}

